<?php

class DataReader {
    private $handle;
    private $tokens = array();
    private $pos = 0;

    public function __construct($handle) {
        $this->handle = $handle;
    }

    public static function createFromFile($name) {
        return new DataReader(fopen($name, "r"));
    }

    public function next() {
        while ($this->pos >= count($this->tokens)) {
            $s = fgets($this->handle);
            if ($s === false) return null;
            $this->tokens = preg_split('/\s+/', trim($s), -1, PREG_SPLIT_NO_EMPTY);
            $this->pos = 0;
        }

        return $this->tokens[$this->pos++];
    }

    public function nextToken() {
        return $this->next();
    }

    public function nextInt() {
        return intval($this->nextToken());
    }

    public function nextLong() {
        return intval($this->nextToken());
    }

    public function readIntArray($n) {
        $result = array_fill(0, $n, 0);
        for ($i = 0; $i < $n; $i++) {
            $result[$i] = $this->nextInt();
        }
        return $result;
    }

    public function nextLine() {
        $s = fgets($this->handle);
        if ($s === false) return null;
        return rtrim($s, "\r\n");
    }

    public function solve($out) {
        $n = $this->nextInt();
        $k = $this->nextInt();

        $s = $this->nextToken();

        $used = array_fill(0, $n, false);

        $dfs = function ($u) use (&$dfs, &$used, $s, $n, $k) {
            if ($u < 0 || $u >= $n || $used[$u] || $s[$u] === '#') return false;
            if ($s[$u] === 'T') return true;
            $used[$u] = true;

            return $dfs($u - $k) || $dfs($u + $k);
        };

        fwrite($out, toYesNo($dfs(strpos($s, 'G'))) . "\n");
    }
}

function toYesNo($value) {
    return $value ? "YES" : "NO";
}

function main() {
    if (getenv("ONLINE_JUDGE") === false) {
        $r = fopen("input.txt", "r");
        $out = fopen("output.txt", "w");
    } else {
        $r = fopen("php://stdin", "r");
        $out = fopen("php://stdout", "w");
    }

    $reader = new DataReader($r);
    $reader->solve($out);
    fflush($out);
}

main();
